 print('green bbox', (np.where(green)[1].min(),np.where(green)[0].min(),np.where(green)[1].max(),np.where(green)[0].max()) if green.any() else None)
 # text candidate dark neutral pixels, excluding hand/table shadow; report non-background gray in tabletop region
 if c=='top':
  for y in range(90,175):
   xs=[]
   for x in range(80,210):
    R,G,B=map(int,im[y,x]); dep=d[y,x]
    if R<155 and G<155 and B<155 and abs(R-G)<25 and abs(G-B)<25 and np.isfinite(dep): xs.append(x)
   if xs: print(y,min(xs),max(xs),len(xs),float(np.median(d[y,min(xs):max(xs)+1])))
