import sys,numpy as np
sys.path.insert(0,'/opt/tools'); from rcb_client import Robot
r=Robot(); o=r.get_obs(cameras=['side','front','top'],include_depth=True,video='frames')
for c in o.last:
 im=o.last[c]; d=o.depth[c][0]
 print('\n'+c)
 if c=='side': roi=(range(110,160),range(80,195))
 elif c=='front': roi=(range(105,165),range(90,220))
 else: roi=(range(50,150),range(70,240))
 for y in roi[0]:
  vals=[]
  for x in roi[1]:
   rgb=im[y,x].astype(int)
   if rgb.max()<210 and np.std(rgb)<65 and d[y,x]<3:
    # don't include highly saturated colors
    vals.append(x)
  # compress segments
  if vals:
   seg=[]; a=p=vals[0]
   for x in vals[1:]:
    if x>p+1: seg.append((a,p)); a=x
    p=x
   seg.append((a,p))
   if any(b-a>2 for a,b in seg): print(y,seg,[(float(d[y,(a+b)//2]),tuple(im[y,(a+b)//2])) for a,b in seg if b-a>2])
