import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['top','side'],include_depth=True,video='frames')
def world(c,mask):
 im=o.last[c];d=o.depth[c][0].astype(float); yy,xx=np.where(mask)
 K=np.array(o.meta['cameras'][c]['intrinsic_cv']);T=np.array(o.meta['cameras'][c]['cam2world_gl']); ray=np.stack([xx,yy,np.ones(len(xx))],1)@np.linalg.inv(K).T;dd=d[yy,xx]
 loc=np.stack([ray[:,0]*dd,-ray[:,1]*dd,-dd,np.ones(len(xx))],1); w=loc@T.T
 return w[:,:3],xx,yy,dd
for c in ['top','side']:
 im=o.last[c].astype(int);d=o.depth[c][0].astype(float); yy,xx=np.mgrid[:240,:320]
 if c=='top':
  m=(xx>=120)&(xx<215)&(yy>=80)&(yy<180)&(d>.7)&(d<.96)&((im.max(2)-im.min(2))<85)&~((im[:,:,1]>im[:,:,0]*1.3)&(im[:,:,1]>im[:,:,2]*1.3))
 else:
  m=(xx>=100)&(xx<165)&(yy>=125)&(yy<148)&(d>.7)&(d<1.10)&((im.max(2)-im.min(2))<50)&(im.min(2)<210)
 pts,x,y,dd=world(c,m);print(c,'N',len(pts),'pixbbox', (x.min(),y.min(),x.max(),y.max()) if len(x) else None)
 if len(pts):
  print('world med',np.median(pts,axis=0),'q25/75',np.percentile(pts,[25,75],axis=0))
  if c=='side': print('rgb med',np.median(im[y,x],axis=0),'depth range',np.percentile(dd,[5,50,95]))
  else:
   # clusters by z
   for lo,hi in [(.70,.83),(.83,.90),(.90,.96)]:
    s=(pts[:,2]>=lo)&(pts[:,2]<hi)
    if s.any():print(lo,hi,len(pts[s]),np.median(pts[s],axis=0),np.percentile(pts[s],[10,90],axis=0))
