 K=np.array(o.meta['cameras'][c]['intrinsic_cv']);T=np.array(o.meta['cameras'][c]['cam2world_gl']);Ki=np.linalg.inv(K)
 if c=='top':
  base=(xx>=125)&(xx<215)&(yy>=70)&(yy<190)&(d>.68)&(d<.96)&((im.max(2)-im.min(2))<90)&~((im[:,:,1]>im[:,:,0]*1.3)&(im[:,:,1]>im[:,:,2]*1.3))
 elif c=='side':
  base=(xx>=105)&(xx<175)&(yy>=122)&(yy<155)&(d>.7)&(d<1.15)&((im.max(2)-im.min(2))<65)&(im.min(2)<220)
 else:
  base=(xx>=125)&(xx<185)&(yy>=55)&(yy<125)&(d>.65)&(d<1.6)&((im.max(2)-im.min(2))<65)&(im.min(2)<220)
 ys,xs=np.where(base);pix=np.stack([xs,ys,np.ones(len(xs))],1);ray=pix@Ki.T;dd=d[ys,xs];loc=np.stack([ray[:,0]*dd,-ray[:,1]*dd,-dd,np.ones(len(xs))],1);w=(loc@T.T)[:,:3]
 print(c,'N',len(xs),'bbox',None if not len(xs) else (xs.min(),ys.min(),xs.max(),ys.max()))
 if len(xs):
  print('world med',np.median(w,axis=0),'range',np.percentile(w,[10,90],axis=0))
